import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { UserService } from 'src/app/services/emis/user.service';
import { UserSessionService } from 'src/app/services/usersession.service';

@Component({
  selector: 'app-view-schedule',
  templateUrl: './view-schedule.page.html',
  styleUrls: ['./view-schedule.page.scss'],
})
export class ViewSchedulePage implements OnInit {
  totalClassData: any[];
  username: any;

  constructor(  private userService: UserService, 
    private usersessionService: UserSessionService,
    private router: Router
    ) { }

  ngOnInit() {
  }

  ionViewDidEnter() {
    this.username = this.usersessionService.emis_username(); 
    this.totalData()
  } 

  totalData(){
      this.totalClassData = []
        this.userService.getschoollistslot(this.username).subscribe((response) => {
         this.totalClassData = response.result
        }) 
    }

    navigateBack() {
      this.router.navigate(['/tabs/school-schedule']);
    }
    

}
